"""Concrete–pictorial–abstract teaching cues, with exact visual state per utterance."""
def r(n,d,label,colour='teal'):return dict(n=n,d=d,label=label,colour=colour)
def c(stage,title,text,rows=(),eq=None,note='',pause=.6,**kw):return dict(stage=stage,chapter=title,text=text,rows=list(rows),equation=eq,note=note,pause=pause,**kw)
C=[
c('A','Who ate more chocolate?',"You and a friend each have a chocolate bar. Both bars are exactly the same size, and both are divided into four equal pieces. You eat three pieces. Your friend eats two. Who ate more chocolate? How could the picture help you explain your answer?",[r(3,4,'Your share: three pieces'),r(2,4,"Your friend’s share: two pieces",'gold')],note='The coloured pieces show how much each person ate.',pause=4,concrete=True,hide=True,tone='question'),
c('A','Comparing fractions: explain why',"You had one more of those equal-sized pieces. Today, we'll discover how to compare fractions, and explain why one amount is greater. We'll begin with pictures, then connect them to fraction numbers.",[r(3,4,'Your share'),r(2,4,"Your friend’s share",'gold')],note='Our goal: compare fractions and explain our reasoning.',concrete=True,hide=True),
c('B','Start with one whole',"Let's build a fraction from the beginning. This rectangle represents one whole chocolate bar. When we divide a whole into parts, the parts must be equal in size. Unequal pieces wouldn't each be a quarter.",[r(1,1,'One whole')],note='One whole → equal parts',hide=True),
c('B','Divide the whole into equal parts',"Here are four equal parts. Now choose three of them. The coloured region shows the amount we've chosen; the whole bar is still the same size.",[r(3,4,'Three of four equal parts')],note='Four equal parts in the whole • Three parts chosen',hide=True,subdivide=[1],reveal=True),
c('B','What does the four tell us?',"We write that amount as three quarters. Look at the four below the fraction bar. What does that four tell us about the whole?",[r(3,4,'Three quarters')],[[3,4]],'Think about all the equal parts, including the uncoloured part.',pause=3,tone='question'),
c('B','Denominator: equal parts in the whole',"Four tells us the whole is divided into four equal parts. We call the bottom number the denominator. It tells us the size of the parts we're using: these are quarters.",[r(3,4,'Four equal parts make one whole')],[[3,4]],'Denominator → how many equal parts make the whole.',annotation='denominator',tone='term',pause=1),
c('B','And what does the three tell us?',"Now look above the fraction bar. What does the three tell us?",[r(3,4,'Count the coloured parts')],[[3,4]],'What has been chosen?',pause=3,tone='question'),
c('B','Numerator: parts chosen',"It tells us that three parts are chosen. The top number is the numerator. Three chosen parts out of four equal parts make three quarters. The fraction and the picture describe the same amount.",[r(3,4,'Three chosen quarter-sized parts')],[[3,4]],'Numerator → how many equal parts are chosen.',annotation='both',tone='term',pause=1),
c('C','Same-sized pieces: make a prediction',"Bring back your friend's bar. You chose three quarters; your friend chose two quarters. Both wholes are the same size, and both use quarter-sized pieces. Before we write a comparison, which coloured amount looks greater? Explain your prediction using the pieces.",[r(3,4,'Your share: three quarters'),r(2,4,"Your friend’s share: two quarters",'gold')],note='Same whole • Same-sized parts',hide=True,pause=4,tone='question'),
c('C','One extra quarter makes the difference',"Look at the ends of the coloured regions. Both shares contain two quarters, but your share has one extra quarter. So three quarters is greater than two quarters. We know why: we're comparing different numbers of pieces that have exactly the same size.",[r(3,4,'Three quarter-sized pieces'),r(2,4,'Two quarter-sized pieces','gold')],note='Three equal pieces cover more than two of the same pieces.',hide=True,pause=1),
c('C','Now connect the picture to the symbol',"Here's how we record that relationship. Three quarters is greater than two quarters. The wide opening of the comparison sign faces the greater amount. When denominators match, compare the numerators, because the equal parts already have the same size.",[r(3,4,'Greater amount'),r(2,4,'Smaller amount','gold')],[[3,4],'>',[2,4]],'Same denominator → compare the number of equal parts chosen.',pause=1),
c('D','One piece from each: which is larger?',"What if the pieces aren't the same size? These two wholes are identical. Divide one into two equal parts and the other into four. If you take just one piece from each whole, which piece will be larger? Look at the size of each piece.",[r(0,2,'Two equal parts'),r(0,4,'Four equal parts','gold')],note='Predict before the pieces are coloured.',hide=True,pause=4,tone='question'),
c('D','Fewer equal parts means larger pieces',"The piece from the first bar is larger. It's one half of the whole; the other piece is one quarter. Cutting the same whole into fewer equal parts makes each piece larger. We chose one piece each time, but those pieces have different sizes.",[r(1,2,'One of two equal parts'),r(1,4,'One of four equal parts','gold')],note='One half covers more of the same whole than one quarter.',hide=True,reveal=True,pause=1),
c('D','A bigger denominator does not mean more',"So one half is greater than one quarter. Notice something important: four is bigger than two, but one quarter is smaller than one half. A bigger denominator means more equal parts in the whole, not bigger pieces. With the same positive numerator, think about piece size.",[r(1,2,'Fewer, larger parts'),r(1,4,'More, smaller parts','gold')],[[1,2],'>',[1,4]],'Same numerator → think about the size of each equal part.',tone='misconception',pause=1),
c('E','Different-sized parts: make a fair comparison',"Now let's compare one half and two thirds. Start with the pictures. Which coloured region reaches further across its whole? Predict which fraction is greater, and think about how you could make the pieces the same size.",[r(1,2,'One half'),r(2,3,'Two thirds','gold')],note='Same-sized wholes, but different-sized parts.',hide=True,pause=4,tone='question'),
c('E','Neither number alone tells the whole story',"The two-thirds region reaches further. But comparing just the top numbers, or just the bottom numbers, isn't a reliable strategy when both are different. We need a fair way to name these amounts using equal-sized pieces. We can divide the existing pieces without changing what's coloured.",[r(1,2,'One half'),r(2,3,'Two thirds','gold')],note='Keep each shaded amount unchanged; change the size of the parts.',hide=True,tone='misconception'),
c('E','Rename the half using sixths',"Split each half into three equal pieces. The whole now contains six equal parts, and the coloured half covers three of them. We haven't added any chocolate. One half is the same amount as three sixths.",[r(3,6,'Three sixths: the same coloured half'),r(2,3,'Two thirds stays visible','gold')],note='The shaded length stays the same.',hide=True,subdivide=[2,3],pause=1,tone='discovery'),
c('E','Equivalent fractions: the same amount',"These are equivalent fractions: different names for the same amount. We can record one half equals three sixths. The picture explains why multiplying both the numerator and denominator by three preserves the fraction's value.",[r(3,6,'One half renamed as three sixths'),r(2,3,'Two thirds','gold')],[[1,2],'=',[3,6]],'Equivalent means equal in value.',tone='term'),
c('E','Rename two thirds using sixths',"Now split each third into two equal pieces. Two coloured thirds become four coloured sixths. Again, the amount hasn't changed. Two thirds equals four sixths. This time, we multiplied both the numerator and denominator by two.",[r(3,6,'Three sixths'),r(4,6,'Four sixths: the same coloured two thirds','gold')],note='Both models now use sixth-sized pieces.',hide=True,subdivide=[6,3],pause=1,tone='discovery'),
c('E','Equal-sized pieces make comparison clear',"Now we can compare three sixths and four sixths. Four sixths is greater, because it contains one more sixth. So one half is less than two thirds. Six is a common denominator: it lets us compare the same-sized pieces. The new names made the comparison clearer.",[r(3,6,'One half equals three sixths'),r(4,6,'Two thirds equals four sixths','gold')],[[1,2],'<',[2,3]],'Three sixths is less than four sixths.',pause=1),
c('F','Your challenge: explain your choice',"It's your turn. Which is greater: two thirds or three quarters? The wholes are equal in size. Use the models, and try to rename both fractions with equal-sized pieces. Think about twelfths. Take five seconds, or pause the video if you'd like more time.",[r(2,3,'Two thirds'),r(3,4,'Three quarters','gold')],[[2,3],'?', [3,4]],'Think first: how could thirds and quarters become twelfths?',pause=5,tone='question'),
c('F','Keep the amount; divide the parts',"Split each third into four equal pieces. The two coloured thirds become eight twelfths. Split each quarter into three equal pieces. Three coloured quarters become nine twelfths. The shaded amounts stay exactly the same; only the divisions change.",[r(8,12,'Eight twelfths: the same as two thirds'),r(9,12,'Nine twelfths: the same as three quarters','gold')],note='Each whole now contains twelve equal parts.',hide=True,subdivide=[3,4],pause=1),
c('F','Use equal parts to justify the answer',"Two thirds equals eight twelfths. Three quarters equals nine twelfths. Nine twelfths has one more twelfth, so three quarters is greater than two thirds. Did your prediction agree? The important part is explaining your answer using equal-sized pieces.",[r(8,12,'Eight twelfths'),r(9,12,'Nine twelfths','gold')],[[2,3],'=',[8,12],'<',[9,12],'=',[3,4]],'Two thirds is less than three quarters.',tone='discovery',pause=1),
c('G','What will you look for first?',"Think back over the lesson. With the same denominator, compare how many equal parts are chosen. With the same numerator, compare the sizes of the pieces. With different denominators, use pictures or equivalent fractions to make a fair comparison. Always check that the wholes are equal in size. When you meet two new fractions, which strategy will you try first, and how will you explain why it works?",note='Same denominator • Same numerator • Equivalent fractions',recap=True,pause=2,tone='recap')
]
# Separate visual actions where a new idea needs its own spoken cue.
for i,x in enumerate(C):
 if x['chapter']=='Divide the whole into equal parts':
  C[i:i+1]=[
   c('B','Four equal parts',"Here are four equal parts. Each part is one quarter of the whole.",[r(0,4,'Four equal-sized parts')],note='Equal parts are essential.',hide=True,subdivide=[1],pause=.5),
   c('B','Choose three of those parts',"Now choose three parts. The coloured region shows the amount we've chosen; the whole bar is still the same size.",[r(3,4,'Three of four equal parts')],note='Four equal parts in the whole • Three parts chosen',hide=True,reveal=True,pause=.6)]
  break
for i,x in enumerate(C):
 if x['chapter']=='Rename two thirds using sixths':
  x['text']="Now split each third into two equal pieces. Two coloured thirds become four coloured sixths. Again, the amount hasn't changed."
  C.insert(i+1,c('E','Two thirds equals four sixths',"Two thirds equals four sixths. We multiplied both the numerator and denominator by two, keeping the same amount.",[r(3,6,'One half is three sixths'),r(4,6,'Two thirds is four sixths','gold')],[[2,3],'=',[4,6]],'Numerator × 2 • Denominator × 2 • Same value',tone='discovery'))
  break
for i,x in enumerate(C):
 if x['chapter']=='Keep the amount; divide the parts':
  C[i:i+1]=[
   c('F','Turn thirds into twelfths',"Split each third into four equal pieces. The two coloured thirds become eight twelfths. The shaded amount stays exactly the same.",[r(8,12,'Eight twelfths: the same as two thirds'),r(3,4,'Three quarters stays visible','gold')],note='Keep the amount; divide the parts.',hide=True,subdivide=[3,4],pause=.7),
   c('F','Record the first equivalent fraction',"So two thirds equals eight twelfths.",[r(8,12,'Eight twelfths'),r(3,4,'Three quarters','gold')],[[2,3],'=',[8,12]],'Two thirds has been renamed using twelfths.',pause=.6),
   c('F','Turn quarters into twelfths',"Split each quarter into three equal pieces. Three coloured quarters become nine twelfths. Again, only the divisions change, not the amount.",[r(8,12,'Eight twelfths'),r(9,12,'Nine twelfths: the same as three quarters','gold')],note='Both models now have twelve equal parts.',hide=True,subdivide=[12,4],pause=.7),
   c('F','Record the second equivalent fraction',"Three quarters equals nine twelfths.",[r(8,12,'Eight twelfths'),r(9,12,'Nine twelfths','gold')],[[3,4],'=',[9,12]],'Three quarters has been renamed using twelfths.',pause=.6)]
  break
for x in C:
 if x['chapter']=='Use equal parts to justify the answer':
  x['text']="Compare eight twelfths with nine twelfths. Nine twelfths has one more twelfth, so three quarters is greater than two thirds. Did your prediction agree? The important part is explaining your answer using equal-sized pieces."
  x['equation']=[[2,3],'<',[3,4]]
 if x['chapter']=='Equivalent fractions: the same amount':x['note']='Numerator × 3 • Denominator × 3 • Same value'
